DROP TABLE IF EXISTS `refunds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `refunds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `shop_id` bigint unsigned NOT NULL,
  `order_id` bigint unsigned NOT NULL,
  `shopify_refund_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shopify_order_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zoho_creditnote_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creditnote_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
